import { Component } from '@angular/core';
import { UserService } from '../user.service';
import { User, UserAuth } from 'src/types/user';
import { FormBuilder, Validators } from '@angular/forms';
import { EMAIL_DOMAINS } from 'src/app/constants';
import { emailValidator } from 'src/app/shared/directives/utils/email-validator';

@Component({
    selector: 'app-profile',
    templateUrl: './profile.component.html',
    styleUrls: ['./profile.component.css']
})
export class ProfileComponent {

    user = {} as User | undefined;
    isEditMode = false;
    emailDomains = EMAIL_DOMAINS;

    form = this.fb.group({
        username: ['', [Validators.required, Validators.minLength(5)]],
        email: ['', [Validators.required, emailValidator(this.emailDomains)]],
        tel: ['']
    });
    constructor(public userService: UserService, private fb: FormBuilder    ) { }

    ngOnInit() {
        this.user = this.userService.user;
    }

    toggleEditMode() {
        this.isEditMode = !this.isEditMode;
    }

    updateProfile() {
        if (this.form.invalid) {
            return;
        }
        console.log(this.form.value);
        // this.user = { ...this.form.value } as User;
        // this.userService.user = { ...this.form.value } as User;
        // console.log(this.form.value);
        this.userService.updateProfile(
            this.form.value.username!,
            this.form.value.email!,
            this.form.value.tel!
        ).subscribe({
            next: () => {
                this.toggleEditMode();
            }
        });
    }

    cancelChanges(e: Event) {
        e.preventDefault();
        this.toggleEditMode();
    }
}
<div class="container">
    <div class="profile"><img
            src="assets/profile.png"
            alt="default user"
        >
        <h3>User Info:</h3>
        <ng-container *ngIf="!isEditMode">
            <div class="flex">
                <p>Username: </p>
                <p>{{user?.username}}</p>
            </div>
            <div class="flex">
                <p>Email: </p>
                <p>{{user?.email}}</p>
            </div>
            <div class="flex">
                <p>Phone: </p>
                <p>{{user?.tel}}</p>
            </div>
            <button
                class="edit-button"
                (click)="toggleEditMode()"
            >Edit</button>
        </ng-container>
        <ng-container *ngIf="isEditMode">
            <form
                [formGroup]="form"
                (ngSubmit)="updateProfile()"
            >
                <div class="flex">
                    <p>Username: </p>
                    <input
                        type="text"
                        name="username"
                        id="username"
                        formControlName="username"
                        [value]="user?.username"
                        required
                        minlength="5"
                    >
                </div>
                <ng-container *ngIf="form.get('username')?.touched">
                    <p
                        class="error"
                        *ngIf="form.get('username')?.errors?.['required']"
                    >Username is
                        required!</p>
                    <p
                        class="error"
                        *ngIf="form.get('username')?.errors?.['minlength']"
                    >Username
                        must be at least 5 characters!</p>
                </ng-container>
                <div class="flex">
                    <p>Email: </p>
                    <input
                        type="email"
                        name="email"
                        id="email"
                        formControlName="email"
                        required
                        [appEmail]="emailDomains"
                    >
                </div>
                <ng-container *ngIf="form.get('email')?.touched">
                    <p
                        class="error"
                        *ngIf="form.get('email')?.errors?.['required']"
                    >Email is
                        required!</p>
                    <p
                        class="error"
                        *ngIf="form.get('email')?.errors?.['emailValidator']"
                    >Email is
                        not valid!</p>
                </ng-container>
                <div class="flex">
                    <p>Phone: </p>
                    <div>
                        <select
                            name="select-tel"
                            id="select-tel"
                            class="tel"
                        >
                            <option value="00359">+359</option>
                        </select>
                        <input
                            type="text"
                            name="tel"
                            id="tel"
                            formControlName="tel"
                        >
                    </div>
                </div>
                <button
                    class="red-button"
                    (click)="cancelChanges($event)"
                >Cancel</button>
                <button>Save</button>
            </form>
        </ng-container>
    </div>
</div>
